export { chainFocus, isValidUrl } from "./commands";
export { extensionPresent, nodeActive } from "./detection";
export { shallowEqual, useEditorState } from "./editor-state";
export { DEFAULT_EXTENSION_LABELS } from "./labels";
export type { ExtensionLabelKey, ExtensionLabels } from "./labels";
export { ToolbarProvider, useToolbar, useToolbarEditor } from "./context";
export type { ToolbarContextValue, ToolbarProviderProps } from "./context";
export type { ToolbarComponentProps } from "./types";

import type { ChainedCommands, Editor } from "@tiptap/core";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean =>
  /^https?:\/\/\S+$/.test(url);

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ExtensionLabels } from "./labels";
import { DEFAULT_EXTENSION_LABELS } from "./labels";

export interface ToolbarContextValue {
  editor: Editor | null;
  labels: ExtensionLabels;
}

const ToolbarContext = createContext<ToolbarContextValue>({
  editor: null,
  labels: DEFAULT_EXTENSION_LABELS,
});

export interface ToolbarProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ExtensionLabels>;
}

export const ToolbarProvider = ({
  children,
  editor = null,
  labels,
}: ToolbarProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_EXTENSION_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <ToolbarContext.Provider value={value}>
      {children}
    </ToolbarContext.Provider>
  );
};

export const useToolbar = (): ToolbarContextValue =>
  useContext(ToolbarContext);

export const useToolbarEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(ToolbarContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
    !editor.isDestroyed &&
    editor.extensionManager.extensions.some(
      (extension) => extension.name === name
    )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import type { Editor } from "@tiptap/core";
import { useCallback, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

const isPlainEmpty = <T>(value: T | undefined): value is undefined =>
  value === undefined;

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);
  selectorRef.current = selector;
  isEqualRef.current = isEqual;

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const computeSnapshot = useCallback((): T | undefined => {
    if (!editor) {
      return undefined;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (isPlainEmpty(current) || !isEqualRef.current(current, next)) {
      snapshotRef.current.value = next;
    }
    return snapshotRef.current.value;
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {};
      }
      const update = () => {
        computeSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, computeSnapshot]
  );

  return useSyncExternalStore(subscribe, computeSnapshot, computeSnapshot);
};

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  highlightColor: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  removeHighlight: string;
  rows: string;
  splitCell: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Add column left",
  addColumnRight: "Add column right",
  addRowAbove: "Add row above",
  addRowBelow: "Add row below",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  highlightColor: "Highlight color",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  removeHighlight: "Remove highlight",
  rows: "Rows",
  splitCell: "Split cell",
};

import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import type { CommandProps, Editor } from "@tiptap/core";
import { mergeAttributes, Node, ReactNodeViewRenderer } from "@tiptap/react";

import { ImagePlaceholderNode } from "./image-placeholder-node";

export { ResizableImage } from "./image";

export interface ImagePlaceholderOptions {
  HTMLAttributes: Record<string, unknown>;
  allowedMimeTypes?: Record<string, string[]>;
  maxFiles?: number;
  maxSize?: number;
  onDrop?: (files: File[], editor: Editor) => void;
  onDropRejected?: (files: File[], editor: Editor) => void;
  onEmbed?: (url: string, editor: Editor) => void;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    imagePlaceholder: {
      insertImagePlaceholder: () => ReturnType;
    };
  }
}

export const ImagePlaceholder = Node.create<ImagePlaceholderOptions>({
  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },
  atom: true,
  group: "block",
  name: "imagePlaceholder",
  addCommands() {
    return {
      insertImagePlaceholder:
        () =>
        ({ commands }: CommandProps) =>
          commands.insertContent({
            type: this.name,
          }),
    };
  },
  parseHTML() {
    return [{ tag: `div[data-type="${this.name}"]` }];
  },
  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": this.name,
      }),
    ];
  },
  addNodeView() {
    return ReactNodeViewRenderer(ImagePlaceholderNode);
  },
});

"use client";

import { Button } from "@components/extensions/ui/button";
import { Input } from "@components/extensions/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@components/extensions/ui/popover";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@components/extensions/ui/tabs";
import { isValidUrl } from "../core/commands";
import { useToolbar } from "../core/context";
import { cn } from "@/lib/utils";
import type { NodeViewProps } from "@tiptap/react";
import { NodeViewWrapper } from "@tiptap/react";
import { Image, Link, Upload } from "lucide-react";
import type { DragEvent, FormEvent } from "react";
import { useCallback, useId, useState } from "react";

export const ImagePlaceholderNode = ({
  editor,
  extension,
  getPos,
  node,
  selected,
}: NodeViewProps) => {
  const { labels } = useToolbar();
  const fileInputId = useId();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [urlError, setUrlError] = useState(false);
  const [isDragActive, setIsDragActive] = useState(false);
  const [isDragReject, setIsDragReject] = useState(false);

  const replaceWithImage = useCallback(
    (src: string) => {
      const pos = getPos();
      if (typeof pos !== "number") {
        return;
      }
      editor
        .chain()
        .focus()
        .insertContentAt(
          { from: pos, to: pos + node.nodeSize },
          { type: "image", attrs: { src } }
        )
        .run();
    },
    [editor, getPos, node.nodeSize]
  );

  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(true);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
    setIsDragReject(false);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
    setIsDragReject(false);

    const { files } = e.dataTransfer;
    const accepted: File[] = [];
    const rejected: File[] = [];

    for (const file of Array.from(files)) {
      const mimeTypes = extension.options.allowedMimeTypes as
        | Record<string, string[]>
        | undefined;
      const tooLarge =
        (extension.options.maxSize as number | undefined) &&
        file.size > (extension.options.maxSize as number);

      if (
        mimeTypes &&
        !Object.keys(mimeTypes).some((type) => file.type.match(type))
      ) {
        rejected.push(file);
      } else if (tooLarge) {
        rejected.push(file);
      } else {
        accepted.push(file);
      }
    }

    if (rejected.length > 0) {
      setIsDragReject(true);
      extension.options.onDropRejected?.(rejected, editor);
    }

    if (accepted.length > 0) {
      handleAcceptedFiles(accepted);
    }
  };

  const handleAcceptedFiles = (files: File[]) => {
    for (const file of files) {
      const reader = new FileReader();
      reader.onload = () => replaceWithImage(reader.result as string);
      reader.readAsDataURL(file);
    }
    extension.options.onDrop?.(files, editor);
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleAcceptedFiles(Array.from(e.target.files || []));
  };

  const handleInsertEmbed = (e: FormEvent) => {
    e.preventDefault();
    if (!isValidUrl(url)) {
      setUrlError(true);
      return;
    }
    replaceWithImage(url);
    extension.options.onEmbed?.(url, editor);
  };

  const mimeTypeList = Object.keys(
    (extension.options.allowedMimeTypes as Record<string, string[]> | undefined) ?? {
      "image/*": ["image/*"],
    }
  ).join(",");

  return (
    <NodeViewWrapper className="w-full">
      <Popover modal open={open} onOpenChange={setOpen}>
        <PopoverTrigger className="w-full">
          <div
            className={cn(
              "flex w-full cursor-pointer items-center gap-3 rounded-md bg-accent px-3 py-3 text-sm text-accent-foreground transition-colors hover:bg-secondary",
              selected && "bg-primary/10 hover:bg-primary/20"
            )}
          >
            <Image className="size-6" />
            {labels.imagePlaceholder}
          </div>
        </PopoverTrigger>
        <PopoverContent className="w-[450px] px-0 py-2">
          <Tabs defaultValue="upload" className="px-3 flex-col">
            <TabsList>
              <TabsTrigger className="px-2 py-1 text-sm" value="upload">
                <Upload className="mr-2 size-4" />
                Upload
              </TabsTrigger>
              <TabsTrigger className="px-2 py-1 text-sm" value="url">
                <Link className="mr-2 size-4" />
                Embed link
              </TabsTrigger>
            </TabsList>
            <TabsContent value="upload">
              <div
                onDragEnter={handleDragEnter}
                onDragLeave={handleDragLeave}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                className={cn(
                  "my-2 rounded-md border border-dashed text-sm transition-colors",
                  isDragActive && "border-primary bg-secondary",
                  isDragReject && "border-destructive bg-destructive/10",
                  "hover:bg-secondary"
                )}
              >
                <input
                  type="file"
                  accept={mimeTypeList}
                  multiple={(extension.options.maxFiles as number | undefined) !== 1}
                  onChange={handleFileInputChange}
                  className="sr-only"
                  id={fileInputId}
                />
                <label
                  htmlFor={fileInputId}
                  className="flex h-28 w-full cursor-pointer flex-col items-center justify-center text-center"
                >
                  <Upload className="mx-auto mb-2 size-6" />
                  Drag & drop or click to upload
                </label>
              </div>
            </TabsContent>
            <TabsContent value="url">
              <form onSubmit={handleInsertEmbed} className="grid gap-2">
                <Input
                  value={url}
                  onChange={(e) => {
                    setUrl(e.target.value);
                    if (urlError) setUrlError(false);
                  }}
                  placeholder="Paste the image link..."
                />
                {urlError ? (
                  <p className="text-xs text-destructive">
                    Please enter a valid URL
                  </p>
                ) : null}
                <Button type="submit" size="sm" className="w-full">
                  Embed Image
                </Button>
                <p className="text-center text-xs text-muted-foreground">
                  Works with any image from the web
                </p>
              </form>
            </TabsContent>
          </Tabs>
        </PopoverContent>
      </Popover>
    </NodeViewWrapper>
  );
};

"use client";

import { Image as TiptapImage } from "@tiptap/extension-image";
import {
  NodeViewContent,
  type NodeViewProps,
  NodeViewWrapper,
  ReactNodeViewRenderer,
} from "@tiptap/react";
import {
  AlignCenter,
  AlignLeft,
  AlignRight,
  Copy,
  Maximize2,
  MoreHorizontal,
  Trash2,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { Button } from "@components/extensions/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@components/extensions/ui/dropdown-menu";
import { Separator } from "@components/extensions/ui/separator";
import { cn } from "@/lib/utils";

export const ResizableImage = TiptapImage.extend({
  addAttributes() {
    return {
      src: { default: null },
      alt: { default: null },
      title: { default: null },
      width: { default: "100%" },
      height: { default: null },
      align: { default: "center" },
    };
  },
  addNodeView: () => ReactNodeViewRenderer(ResizableImageNode),
}).configure({ allowBase64: true });

function ResizableImageNode({
  node,
  editor,
  selected,
  deleteNode,
  updateAttributes,
  getPos,
}: NodeViewProps) {
  const imageRef = useRef<HTMLImageElement | null>(null);
  const nodeRef = useRef<HTMLDivElement | null>(null);
  const [resizing, setResizing] = useState(false);
  const [resizingPosition, setResizingPosition] = useState<"left" | "right">(
    "left"
  );
  const [resizeInitialWidth, setResizeInitialWidth] = useState(0);
  const [resizeInitialMouseX, setResizeInitialMouseX] = useState(0);
  const [openedMore, setOpenedMore] = useState(false);

  const resize = (event: MouseEvent) => {
    if (!resizing) return;
    let dx = event.clientX - resizeInitialMouseX;
    if (resizingPosition === "left") {
      dx = resizeInitialMouseX - event.clientX;
    }
    const newWidth = Math.max(resizeInitialWidth + dx, 150);
    const parentWidth = nodeRef.current?.parentElement?.offsetWidth || 0;
    if (newWidth < parentWidth) {
      updateAttributes({ width: newWidth });
    }
  };

  const endResize = () => {
    setResizing(false);
    setResizeInitialMouseX(0);
    setResizeInitialWidth(0);
  };

  const handleMouseDown = (position: "left" | "right") => {
    return (event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
      setResizing(true);
      setResizingPosition(position);
      setResizeInitialMouseX(event.clientX);
      if (imageRef.current) {
        setResizeInitialWidth(imageRef.current.offsetWidth);
      }
    };
  };

  const handleTouchStart = (position: "left" | "right") => {
    return (event: React.TouchEvent) => {
      event.preventDefault();
      const touch = event.touches[0];
      if (!touch) return;
      setResizing(true);
      setResizingPosition(position);
      setResizeInitialMouseX(touch.clientX);
      if (imageRef.current) {
        setResizeInitialWidth(imageRef.current.offsetWidth);
      }
    };
  };

  const handleTouchMove = (event: TouchEvent) => {
    if (!resizing) return;
    const touch = event.touches[0];
    if (!touch) return;
    let dx = touch.clientX - resizeInitialMouseX;
    if (resizingPosition === "left") {
      dx = resizeInitialMouseX - touch.clientX;
    }
    const newWidth = Math.max(resizeInitialWidth + dx, 150);
    const parentWidth = nodeRef.current?.parentElement?.offsetWidth || 0;
    if (newWidth < parentWidth) {
      updateAttributes({ width: newWidth });
    }
  };

  const handleTouchEnd = () => {
    setResizing(false);
    setResizeInitialMouseX(0);
    setResizeInitialWidth(0);
  };

  useEffect(() => {
    window.addEventListener("mousemove", resize);
    window.addEventListener("mouseup", endResize);
    window.addEventListener("touchmove", handleTouchMove);
    window.addEventListener("touchend", handleTouchEnd);
    return () => {
      window.removeEventListener("mousemove", resize);
      window.removeEventListener("mouseup", endResize);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleTouchEnd);
    };
  }, [resizing, resizeInitialMouseX, resizeInitialWidth]);

  const duplicate = () => {
    const pos = getPos();
    if (typeof pos !== "number" || !editor || editor.isDestroyed) return;
    editor
      .chain()
      .focus()
      .insertContentAt(pos + node.nodeSize, node.toJSON())
      .run();
  };

  return (
    <NodeViewWrapper
      ref={nodeRef}
      className={cn(
        "group relative flex flex-col rounded-md",
        selected && "ring-2 ring-ring ring-offset-2",
        node.attrs.align === "left" && "left-0 -translate-x-0",
        node.attrs.align === "center" && "left-1/2 -translate-x-1/2",
        node.attrs.align === "right" && "left-full -translate-x-full"
      )}
      style={{ width: node.attrs.width }}
    >
      <img
        ref={imageRef}
        className="rounded-md"
        src={node.attrs.src}
        alt={node.attrs.alt}
        title={node.attrs.title}
      />
      {node.attrs.title ? (
        <NodeViewContent className="pt-1.5 text-center text-sm text-muted-foreground">
          {node.attrs.title}
        </NodeViewContent>
      ) : null}

      {editor?.isEditable && (
        <>
          <div
            className="absolute inset-y-0 z-20 flex w-4 cursor-col-resize items-center justify-start"
            style={{ left: 0 }}
            onMouseDown={handleMouseDown("left")}
            onTouchStart={handleTouchStart("left")}
          >
            <div
              className={cn(
                "h-16 w-1 rounded-full bg-primary opacity-0 transition-opacity group-hover:opacity-100",
                resizing && "opacity-100"
              )}
            />
          </div>
          <div
            className="absolute inset-y-0 z-20 flex w-4 cursor-col-resize items-center justify-end"
            style={{ right: 0 }}
            onMouseDown={handleMouseDown("right")}
            onTouchStart={handleTouchStart("right")}
          >
            <div
              className={cn(
                "h-16 w-1 rounded-full bg-primary opacity-0 transition-opacity group-hover:opacity-100",
                resizing && "opacity-100"
              )}
            />
          </div>
          <div
            className={cn(
              "absolute right-0 top-full mt-2 flex items-center gap-1 rounded-lg border border-border bg-popover p-1 shadow-md transition-opacity",
              !resizing && "opacity-0 group-hover:opacity-100",
              (selected || openedMore) && "opacity-100"
            )}
          >
            <Button
              className={cn(
                "size-7",
                node.attrs.align === "left" && "bg-accent text-accent-foreground"
              )}
              data-active={node.attrs.align === "left" || undefined}
              aria-label="Align left"
              size="icon"
              variant="ghost"
              onClick={() => updateAttributes({ align: "left" })}
            >
              <AlignLeft className="size-4" />
            </Button>
            <Button
              className={cn(
                "size-7",
                node.attrs.align === "center" && "bg-accent text-accent-foreground"
              )}
              data-active={node.attrs.align === "center" || undefined}
              aria-label="Align center"
              size="icon"
              variant="ghost"
              onClick={() => updateAttributes({ align: "center" })}
            >
              <AlignCenter className="size-4" />
            </Button>
            <Button
              className={cn(
                "size-7",
                node.attrs.align === "right" && "bg-accent text-accent-foreground"
              )}
              data-active={node.attrs.align === "right" || undefined}
              aria-label="Align right"
              size="icon"
              variant="ghost"
              onClick={() => updateAttributes({ align: "right" })}
            >
              <AlignRight className="size-4" />
            </Button>
            <Separator orientation="vertical" className="h-5" />
            <DropdownMenu open={openedMore} onOpenChange={setOpenedMore}>
              <DropdownMenuTrigger
                render={<Button aria-label="Image options" className="size-7" size="icon" variant="ghost" />}
              >
                <MoreHorizontal className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent className="text-sm">
                <DropdownMenuItem onClick={duplicate}>
                  <Copy className="mr-2 size-4" /> Duplicate
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={() => updateAttributes({ width: "fit-content" })}
                >
                  <Maximize2 className="mr-2 size-4" /> Full width
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  variant="destructive"
                  onClick={() => deleteNode()}
                >
                  <Trash2 className="mr-2 size-4" /> Delete image
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </>
      )}
    </NodeViewWrapper>
  );
}

"use client";

import { Button } from "@components/extensions/ui/button";
import { cn } from "@/lib/utils";
import { useToolbar, useToolbarEditor } from "../core/context";
import { useEditorState } from "../core/editor-state";
import { Image } from "lucide-react";
import type { ToolbarComponentProps } from "../core/types";

export const ImagePlaceholderToolbar = ({
  className,
  editor: editorProp,
  size = "icon-sm",
}: ToolbarComponentProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);

  const disabled =
    useEditorState(
      editor,
      (edit) =>
        edit.isDestroyed ||
        !edit.extensionManager.extensions.some(
          (e) => e.name === "imagePlaceholder"
        )
    ) ?? true;

  return (
    <Button
      aria-label={labels.image}
      className={cn("data-active:bg-accent data-active:text-accent-foreground", className)}
      disabled={disabled}
      size={size}
      title={labels.image}
      variant="ghost"
      onClick={() => {
        if (editor && !editor.isDestroyed && !disabled) {
          editor.chain().focus().insertImagePlaceholder().run();
        }
      }}
    >
      <Image />
    </Button>
  );
};

"use client";

import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { cn } from "@/lib/utils";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";

const Tabs = ({
  className,
  orientation = "horizontal",
  ...props
}: TabsPrimitive.Root.Props) => (
  <TabsPrimitive.Root
    data-slot="tabs"
    data-orientation={orientation}
    className={cn("group/tabs flex gap-2 data-horizontal:flex-col", className)}
    {...props}
  />
);

const tabsListVariants = cva(
  "group/tabs-list inline-flex w-fit items-center justify-center rounded-none p-[3px] text-muted-foreground group-data-horizontal/tabs:h-8 group-data-vertical/tabs:h-fit group-data-vertical/tabs:flex-col data-[variant=line]:rounded-none",
  {
    defaultVariants: {
      variant: "default",
